/* Packed tables: unpacked once, into heap memory that lives as long as the process (the language is a singleton).
   The unpacker, the once-only guard and the failure exit are in src/userland/ts_packed.cpp. */
extern int aios_ts_unpack(const unsigned char *z, unsigned long zlen, unsigned long rawlen, unsigned stride, void *out);
extern const void *aios_ts_alloc(unsigned long bytes);
extern int aios_ts_begin(int *state);   /* 1: this caller unpacks; 0: already done (waits if another thread is at it) */
extern void aios_ts_end(int *state);
extern void aios_ts_fail(void);
static const void *aios_ts_table(const unsigned char *z, unsigned long zlen, unsigned long rawlen, unsigned stride) {
  void *p = (void *)aios_ts_alloc(rawlen);
  if (!p || !aios_ts_unpack(z, zlen, rawlen, stride, p)) aios_ts_fail();
  return p;
}

